        vertical_beams.append(beam)

    # Create horizontal beams connecting vertical beams
    for i in range(len(x_positions) - 1):
        x1 = x_positions[i]
        x2 = x_positions[i + 1]
        beam = sandbox.add_beam(x=(x1 + x2) / 2, y=10.5, width=0.1, height=0.1, density=10.0, friction=0.5)

        # Connect horizontal beam to vertical beams at y=10.5m
        joint1 = sandbox.add_joint(beam, vertical_beams[i], anchor_point=(x1, 10.5), type='rigid')
        joint2 = sandbox.add_joint(beam, vertical_beams[i + 1], anchor_point=(x2, 10.5), type='rigid')

    # Anchor vertical beams at x=10.0 and x=25.0 to the cliffs
    for x in [10.0, 25.0]:
        for beam in vertical_beams:
            if abs(beam.position.x - x) < 1e-6:
